import fs from 'node:fs';
import assert from 'node:assert/strict';
import path from 'node:path';
import {pathToFileURL} from 'node:url';
const [code,fixture]=process.argv.slice(2);
if (!code||!fixture) throw Error('Usage: node replay.mjs CHECKOUT before-region-eight.json');
const {createGenerationHarness}=await import(pathToFileURL(path.resolve(code,'test/helpers/generation-harness.mjs')).href);
const source=JSON.parse(fs.readFileSync(fixture,'utf8')), seed=1257875020, anchor={q:0,r:-3};
const results=[];
for (const [rerolls,edit] of [[1,'none'],[2,'none'],[1,'note-only'],[1,'before'],[1,'after']]){
 const harness=createGenerationHarness(seed,'','en'), ui=()=>harness.render();
 let consent=true;
 const prompts=[];
 harness.setWindow({confirm:message=>(prompts.push(message),consent),alert:message=>{throw Error(message)}});
 harness.injectFunction('readTextFile',file=>file.text);
 await ui().handleImportJson({target:{files:[{text:JSON.stringify(source)}],value:'file'}});
 ui().setGenSizeCategory('locality');
 const save=()=>{const doc=JSON.parse(JSON.stringify(ui().createSaveData()));delete doc.savedAt;return doc;};
 const layer=doc=>doc.map.physicalGrid.smallLakes;
 const ids=doc=>layer(doc).lakes.map(l=>l.id);
 const missing=(a,b)=>ids(a).filter(id=>!ids(b).includes(id));
 const before=save();
 ui().generateAt(anchor);const expansion=save();
 assert.equal(expansion.map.regions.length,8);assert.deepEqual(missing(before,expansion),[24]);assert.deepEqual(missing(expansion,before),[34,35]);
 function manualDelete(){const old=layer(before).lakes.find(l=>l.id===1);assert.ok(ui().switchFineStep(1));assert.ok(ui().pickFine(old.cells[0],false,ui().getDocumentRevision()));ui().removeSelectedSmallLake();assert.ok(!ids(save()).includes(1));assert.ok(ui().switchFineStep(6));}
 function note(){ui().setSelectedHex({q:0,r:1});ui().changeNotesText('0,1','edited');ui().finishNotesGroup();}
 if(edit==='before'){manualDelete();note();}
 const counters=[];
 for(let i=0;i<rerolls;i++){
  const previous=save();ui().regenerateLastRegion();assert.ok(ui().pendingRegen);ui().finishPendingRegeneration();assert.ok(!ui().generationError,ui().generationError);
  const result=save();assert.equal(result.map.regions.length,8);counters.push(layer(result).nextId);
  ui().undoMap();assert.deepEqual(save(),previous);ui().redoMap();assert.deepEqual(save(),result);
 }
 if(edit==='after'){manualDelete();note();}
 if(edit==='note-only')note();
 const preDelete=save();consent=false;ui().deleteLastRegion();assert.deepEqual(save(),preDelete);consent=true;ui().deleteLastRegion();
 const returned=save();assert.equal(returned.map.regions.length,7);
 ui().undoMap();assert.deepEqual(save(),preDelete);ui().redoMap();assert.deepEqual(save(),returned);
 const lakeEdits=edit==='before'||edit==='after';
 if(lakeEdits){assert.ok(!ids(returned).includes(1));assert.equal(returned.map.gmNotesByHexKey['0,1'],'edited');}
 else {const expected=structuredClone(before.map);if(edit==='note-only')expected.gmNotesByHexKey['0,1']='edited';assert.deepEqual(returned.map,expected);}
 const restoredLakes=layer(returned).lakes;
 const restoreState={countBefore:ids(before).length,countAfter:ids(returned).length,missing:missing(before,returned),extra:missing(returned,before),nextId:layer(returned).nextId,survivorsExact:restoredLakes.every(l=>JSON.stringify(l)===JSON.stringify(layer(before).lakes.find(o=>o.id===l.id)))};
 assert.ok(restoreState.survivorsExact);
 let repeatIds=null;
 if(edit==='none'){ui().generateAt(anchor);const newMap=save();assert.equal(newMap.map.regions.length,8);repeatIds=missing(newMap,returned);ui().undoMap();assert.deepEqual(save(),returned);ui().generateAt(anchor);assert.deepEqual(save(),newMap);}
 const one={rerolls,edit,nextAtRerolls:counters,restoreState,rerollUndoRedoExact:true,deletionUndoRedoExact:true,declinedDeletionExact:true,repeatIds,repeatAfterUndoExact:repeatIds?true:null,prompts};
 results.push(one);
}
console.log(JSON.stringify({head:'bb2955254240ef28c9135b34f81b5a2b8985868a',seed,anchor,results},null,2));
